    35  template <typename Driver>
    36  struct hb_kern_machine_t
    37  {
    38    hb_kern_machine_t (const Driver &driver_) : driver (driver_) {}
    39
    40    inline void kern (hb_font_t *font,
    41                      hb_buffer_t  *buffer,
    42                      hb_mask_t kern_mask) const
    43    {
    44      OT::hb_ot_apply_context_t c (1, font, buffer);
    45      c.set_lookup_mask (kern_mask);
    46      c.set_lookup_props (OT::LookupFlag::IgnoreMarks);
    47      OT::hb_ot_apply_context_t::skipping_iterator_t &skippy_iter = c.iter_input;
    48      skippy_iter.init (&c);
    49
    50      bool horizontal = HB_DIRECTION_IS_HORIZONTAL (buffer->props.direction);
    51      unsigned int count = buffer->len;
    52      hb_glyph_info_t *info = buffer->info;
    53      hb_glyph_position_t *pos = buffer->pos;
    54      for (unsigned int idx = 0; idx < count;)
    55      {
    56        if (!(info[idx].mask & kern_mask))
    57        {
    58          idx++;
    59          continue;
    60        }
    61
    62        skippy_iter.reset (idx, 1);
    63        if (!skippy_iter.next ())
    64        {
    65          idx++;
    66          continue;
    67        }
    68
    69        unsigned int i = idx;
    70        unsigned int j = skippy_iter.idx;
    71        hb_position_t kern1, kern2;
    72
    73        hb_position_t kern = driver.get_kerning (info[i].codepoint,
    74                                                 info[j].codepoint);
    75
    76
    77        if (likely (!kern))
    78          goto skip;
    79
    80        kern1 = kern >> 1;
